CREATE TABLE public.wedding_private (wedding_id uuid PRIMARY KEY REFERENCES public.weddings(id) ON DELETE CASCADE, settings jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT ON public.wedding_private TO authenticated;
GRANT ALL ON public.wedding_private TO service_role;
ALTER TABLE public.wedding_private ENABLE ROW LEVEL SECURITY;
CREATE POLICY wedding_private_managers ON public.wedding_private FOR SELECT TO authenticated USING (public.owns_wedding(wedding_id) OR EXISTS (SELECT 1 FROM public.weddings w WHERE w.id=wedding_id AND w.planner_user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.sync_wedding_private() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.wedding_private(wedding_id,settings) VALUES (NEW.id,jsonb_build_object('pix_key',NEW.pix_key,'pix_holder',NEW.pix_holder,'notify_whatsapp',NEW.notify_whatsapp,'commission_percent',NEW.commission_percent,'commission_paid_by',NEW.commission_paid_by,'approval_note',NEW.approval_note,'approved_by',NEW.approved_by,'plan',NEW.plan,'plan_fee_cents',NEW.plan_fee_cents,'plan_billing',NEW.plan_billing,'plan_paid',NEW.plan_paid,'plan_started_on',NEW.plan_started_on,'plan_notes',NEW.plan_notes,'planner_name',NEW.planner_name,'planner_contact',NEW.planner_contact,'planner_pix',NEW.planner_pix,'planner_percent',NEW.planner_percent,'planner_user_id',NEW.planner_user_id)) ON CONFLICT(wedding_id) DO UPDATE SET settings=excluded.settings; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.sync_wedding_private() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER wedding_private_sync AFTER INSERT OR UPDATE ON public.weddings FOR EACH ROW EXECUTE FUNCTION public.sync_wedding_private();
INSERT INTO public.wedding_private(wedding_id,settings) SELECT id,jsonb_build_object('pix_key',pix_key,'pix_holder',pix_holder,'notify_whatsapp',notify_whatsapp,'commission_percent',commission_percent,'commission_paid_by',commission_paid_by,'approval_note',approval_note,'approved_by',approved_by,'plan',plan,'plan_fee_cents',plan_fee_cents,'plan_billing',plan_billing,'plan_paid',plan_paid,'plan_started_on',plan_started_on,'plan_notes',plan_notes,'planner_name',planner_name,'planner_contact',planner_contact,'planner_pix',planner_pix,'planner_percent',planner_percent,'planner_user_id',planner_user_id) FROM public.weddings;
CREATE VIEW public.wedding_public WITH (security_barrier=true) AS SELECT id,slug,bride_name,groom_name,wedding_date,venue,welcome_message,cover_image_url,published,created_at,updated_at,tagline,story_how_we_met,story_proposal,story_text,ceremony_venue,ceremony_address,ceremony_time,ceremony_map_url,party_venue,party_address,party_time,party_map_url,party_image_url,dress_code,tips,hashtag,rsvp_deadline,theme_template,theme_primary,theme_accent,theme_background,theme_font_display,theme_font_body,approval_status,hero_opacity,hero_height,hero_rotate_seconds,music_url,music_title,music_enabled,music_autoplay,hero_fit,hero_text_color,hero_pos_x,hero_pos_y,bride_photo_url,groom_photo_url,couple_intro,monogram,require_login,hero_title FROM public.weddings WHERE published AND approval_status='approved';
GRANT SELECT ON public.wedding_public TO anon,authenticated,service_role;
DROP POLICY "anon weddings readable" ON public.weddings;
DROP POLICY "auth weddings readable" ON public.weddings;
CREATE POLICY "auth weddings managers only" ON public.weddings FOR SELECT TO authenticated USING (public.owns_wedding(id));
DO $$ DECLARE r record; q text; BEGIN FOR r IN SELECT tablename,policyname,qual FROM pg_policies WHERE schemaname='public' AND tablename IN ('gifts','wedding_people','wedding_photos','wedding_announcements','wedding_messages') AND qual ILIKE '%FROM weddings w%' LOOP q := replace(r.qual,'FROM weddings w','FROM public.wedding_public w'); EXECUTE format('ALTER POLICY %I ON public.%I USING (%s)',r.policyname,r.tablename,q); END LOOP; END $$;
COMMENT ON TABLE public.wedding_private IS 'Protected internal settings mirror. Legacy weddings fields remain manager-only for backward-compatible writes; sync trigger keeps the protected copy current.';
COMMENT ON VIEW public.wedding_public IS 'Explicit public presentation projection. Intentionally owner-executed with publication filter; excludes all financial, contact, approval and plan internals.';